//! Raw ODBC bindings, generated by bindgen from the system's unixODBC headers,
//! so every handle and integer type is the C typedef itself.
//!
//! Without the `unixodbc` feature the crate is empty.
#![cfg(feature = "unixodbc")]

// bindgen's output, and so which lints fire on it, differs per unixODBC version,
// so an expectation would go unfulfilled on some: zend-sys's exception, for the
// same reason.
mod bindings {
    #![allow(
        non_camel_case_types,
        non_upper_case_globals,
        non_snake_case,
        dead_code,
        unsafe_op_in_unsafe_fn,
        clippy::all,
        clippy::pedantic,
        clippy::restriction,
        clippy::nursery,
        reason = "generated by bindgen from the ODBC headers"
    )]
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub use bindings::*;
